package br.com.onda;
import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import android.os.*;
import android.provider.OpenableColumns;
import android.text.InputType;
import android.text.InputFilter;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** A single quiet workspace: explicit navigation, local references, no background scanner. */
@androidx.media3.common.util.UnstableApi
public class ShelfActivity extends Activity {
 private static final int PICK=710;private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private LinearLayout content;private TextView status;private Button recentTab,collectionsTab,add;private String group="",pickerGroup="";private boolean groups,busy;private MediaShelf shelf;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);if(saved!=null){group=saved.getString("group","");groups=saved.getBoolean("groups");pickerGroup=saved.getString("pickerGroup","");}
  LinearLayout root=column();Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);Button back=Ui.button(this,"‹",v->{if(!group.isEmpty()){group="";render();}else finish();});back.setContentDescription("Voltar do Meu espaço");Ui.ghost(back);header.addView(back,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));TextView title=Ui.text(this,"Meu espaço",23,Ui.TEXT);Ui.bold(title);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button help=Ui.button(this,"?",v->new AlertDialog.Builder(this).setTitle("Continuar e coleções").setMessage("Retome áudio, vídeo e PDF e reúna referências em coleções. Segure um arquivo para adicionar anotações ligadas a um minuto ou página.\n\nTudo fica neste celular, sem API paga. Não duplica nem exclui os arquivos originais. Arquivos removidos ou sem acesso precisam ser selecionados novamente. Até 200 referências, 30 coleções, 50 arquivos por coleção e 10 notas de 1.000 caracteres por arquivo. O backup de listas atual não inclui este espaço.").setPositiveButton("Entendi",null).show());help.setContentDescription("Ajuda do Meu espaço");header.addView(help,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));root.addView(header);
  LinearLayout tabs=new LinearLayout(this);recentTab=Ui.button(this,"Continuar",v->{groups=false;group="";render();});collectionsTab=Ui.button(this,"Coleções",v->{groups=true;group="";render();});tabs.addView(recentTab,new LinearLayout.LayoutParams(0,-2,1));tabs.addView(collectionsTab,new LinearLayout.LayoutParams(0,-2,1));root.addView(tabs);
  status=Ui.text(this,"",13,Ui.MUTED);status.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,12));status.setContentDescription("Estado do Meu espaço");root.addView(status);
  ScrollView scroll=new ScrollView(this);content=column();scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));add=Ui.button(this,"",v->{if(groups&&group.isEmpty())collectionName(null);else if(!group.isEmpty())addOptions();else pick();});add.setContentDescription("Adicionar no Meu espaço");root.addView(add,new LinearLayout.LayoutParams(-1,-2));
 }
 private LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}
 @Override protected void onResume(){super.onResume();render();}
 @Override protected void onSaveInstanceState(Bundle state){state.putString("pickerGroup",pickerGroup);state.putString("group",group);state.putBoolean("groups",groups);super.onSaveInstanceState(state);}
 private String kind(MediaShelf.Item item){return item.type.equals("pdf")?"PDF":item.type.equals("video")?"Vídeo":"Áudio";}
 private String point(MediaShelf.Item i,long at){return i.type.equals("pdf")?"Página "+(at+1):VideoLoop.time(at);}
 private String progress(MediaShelf.Item i){return kind(i)+" • "+point(i,i.position)+(i.duration>0?i.type.equals("pdf")?" de "+i.duration:" / "+VideoLoop.time(i.duration):"")+(i.notes.isEmpty()?"":" • "+i.notes.size()+" nota(s)");}
 private void render(){if(isDestroyed())return;shelf=ShelfStore.read(this);content.removeAllViews();Ui.chip(recentTab,!groups);Ui.chip(collectionsTab,groups);add.setEnabled(shelf.valid&&!busy);
  if(!shelf.valid){status.setText("Não foi possível ler o espaço local. Os dados foram preservados.");return;}
  if(!group.isEmpty()&&!shelf.collections.containsKey(group))group="";
  if(groups&&group.isEmpty()){status.setText("Coleções com áudios, vídeos e PDFs juntos");add.setText("Criar coleção");for(MediaShelf.Collection c:shelf.collections.values()){LinearLayout row=Ui.result(this,c.name,c.items.size()+" arquivo(s)",c.id.hashCode(),v->{group=c.id;render();});row.setContentDescription("Abrir coleção "+c.name);row.setOnLongClickListener(v->{collectionActions(c);return true;});content.addView(row);}if(shelf.collections.isEmpty())empty("Crie uma coleção para reunir uma aula, a apostila e seus áudios, por exemplo.");}
  else{List<MediaShelf.Item> entries=new ArrayList<>();if(group.isEmpty()){status.setText("Continuar de onde parei • arquivos locais");entries.addAll(shelf.recent());add.setText("Adicionar arquivo");}else{MediaShelf.Collection c=shelf.collections.get(group);status.setText(c.name+" • "+c.items.size()+" arquivo(s)");for(String id:c.items)if(shelf.items.containsKey(id))entries.add(shelf.items.get(id));add.setText("Adicionar à coleção");}
   for(MediaShelf.Item i:entries){LinearLayout row=Ui.result(this,i.title,progress(i),i.type.hashCode(),v->open(i,i.position));row.setContentDescription("Retomar "+i.title);row.setOnLongClickListener(v->{itemActions(i);return true;});content.addView(row);}if(entries.isEmpty())empty(group.isEmpty()?"Ouça um áudio, assista a um vídeo ou abra um PDF. Seus próximos pontos de retomada aparecerão aqui. Segure um arquivo para anotar ou organizar.":"Adicione arquivos ou escolha itens de Continuar. Segure o nome da coleção para renomear ou excluir.");}
 }
 private void empty(String message){TextView text=Ui.text(this,message,16,Ui.MUTED);text.setPadding(Ui.dp(this,10),Ui.dp(this,20),Ui.dp(this,10),Ui.dp(this,20));content.addView(text);}
 private void changed(boolean ok){if(!ok)Toast.makeText(this,"Não foi possível salvar. Verifique os limites e tente novamente.",Toast.LENGTH_LONG).show();render();}
 private void collectionName(MediaShelf.Collection previous){EditText name=new EditText(this);Ui.input(name);name.setContentDescription("Nome da coleção multimídia");name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(60)});if(previous!=null)name.setText(previous.name);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(previous==null?"Criar coleção":"Renomear coleção").setView(name).setPositiveButton("Salvar",null).setNegativeButton("Cancelar",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String label=MediaShelf.clean(name.getText().toString(),60);if(label.isEmpty()){name.setError("Digite um nome");return;}boolean ok=ShelfStore.edit(this,s->{if(previous==null){MediaShelf.Collection c=s.create(label);if(c!=null){group=c.id;groups=true;}return c!=null;}MediaShelf.Collection c=s.collections.get(previous.id);if(c==null)return false;c.name=label;return true;});dialog.dismiss();changed(ok);}));dialog.show();}
 private void collectionActions(MediaShelf.Collection c){new AlertDialog.Builder(this).setTitle(c.name).setItems(new String[]{"Abrir coleção","Renomear","Excluir coleção"},(d,w)->{if(w==0){group=c.id;render();}else if(w==1)collectionName(c);else new AlertDialog.Builder(this).setTitle("Excluir coleção?").setMessage("Remove apenas esta organização. Os arquivos e as anotações permanecem no celular.").setPositiveButton("Excluir",(x,y)->changed(ShelfStore.edit(this,s->{MediaShelf.Collection removed=s.collections.remove(c.id);if(removed==null)return false;for(String id:removed.items){MediaShelf.Item i=s.items.get(id);if(i!=null&&i.seen==0&&!i.notes.isEmpty())i.seen=System.currentTimeMillis();}return true;}))).setNegativeButton("Cancelar",null).show();}).setNegativeButton("Fechar",null).show();}
 private void addOptions(){new AlertDialog.Builder(this).setTitle("Adicionar à coleção").setItems(new String[]{"Escolher arquivo do celular","Escolher de Continuar"},(d,w)->{if(w==0)pick();else{List<MediaShelf.Item> list=shelf.recent();if(list.isEmpty()){Toast.makeText(this,"Nenhum arquivo recente",Toast.LENGTH_SHORT).show();return;}String[] labels=new String[list.size()];for(int n=0;n<labels.length;n++)labels[n]=kind(list.get(n))+" • "+list.get(n).title;new AlertDialog.Builder(this).setTitle("Escolher arquivo").setItems(labels,(x,n)->changed(ShelfStore.edit(this,s->s.add(group,list.get(n).id)))).setNegativeButton("Cancelar",null).show();}}).setNegativeButton("Cancelar",null).show();}
 private void itemActions(MediaShelf.Item item){String[] options=group.isEmpty()?new String[]{"Retomar arquivo","Nova anotação","Ver anotações","Adicionar a uma coleção","Ocultar de Continuar"}:new String[]{"Retomar arquivo","Nova anotação","Ver anotações","Adicionar a uma coleção","Remover desta coleção"};String owner=group;new AlertDialog.Builder(this).setTitle(item.title).setItems(options,(d,w)->{if(w==0)open(item,item.position);else if(w==1)note(item,null);else if(w==2)notes(item);else if(w==3)chooseCollection(item);else if(owner.isEmpty()&&!item.notes.isEmpty()&&!shelf.pinned(item.id))Toast.makeText(this,"Adicione este arquivo a uma coleção antes de ocultar suas anotações.",Toast.LENGTH_LONG).show();else changed(ShelfStore.edit(this,s->{MediaShelf.Item current=s.items.get(item.id);if(current==null)return false;if(owner.isEmpty()){if(!current.notes.isEmpty()&&!s.pinned(current.id))return false;current.seen=0;}else{MediaShelf.Collection c=s.collections.get(owner);if(c==null)return false;c.items.remove(item.id);}return true;}));}).setNegativeButton("Fechar",null).show();}
 private void chooseCollection(MediaShelf.Item item){List<MediaShelf.Collection> groups=new ArrayList<>(shelf.collections.values());if(groups.isEmpty()){Toast.makeText(this,"Crie uma coleção na aba Coleções",Toast.LENGTH_LONG).show();return;}String[] labels=new String[groups.size()];for(int i=0;i<labels.length;i++)labels[i]=groups.get(i).name;new AlertDialog.Builder(this).setTitle("Adicionar à coleção").setItems(labels,(d,w)->changed(ShelfStore.edit(this,s->s.add(groups.get(w).id,item.id)))).setNegativeButton("Cancelar",null).show();}
 private void notes(MediaShelf.Item item){if(item.notes.isEmpty()){note(item,null);return;}String[] labels=new String[item.notes.size()];for(int i=0;i<labels.length;i++){MediaShelf.Note n=item.notes.get(i);labels[i]=point(item,n.at)+" • "+MediaShelf.clean(n.text,80);}new AlertDialog.Builder(this).setTitle("Anotações • "+item.title).setItems(labels,(d,w)->{MediaShelf.Note n=item.notes.get(w);new AlertDialog.Builder(this).setTitle(point(item,n.at)).setMessage(n.text).setPositiveButton("Abrir ponto",(x,y)->open(item,n.at)).setNeutralButton("Editar",(x,y)->note(item,n)).setNegativeButton("Excluir",(x,y)->new AlertDialog.Builder(this).setTitle("Excluir anotação?").setPositiveButton("Excluir",(a,b)->changed(ShelfStore.edit(this,s->{MediaShelf.Item current=s.items.get(item.id);return current!=null&&current.notes.removeIf(v->v.id.equals(n.id));}))).setNegativeButton("Cancelar",null).show()).show();}).setPositiveButton("Nova anotação",(d,w)->note(item,null)).setNegativeButton("Fechar",null).show();}
 private void note(MediaShelf.Item item,MediaShelf.Note previous){if(previous==null&&item.duration<=0){Toast.makeText(this,"Abra este arquivo uma vez para identificar a duração ou o número de páginas antes de anotar.",Toast.LENGTH_LONG).show();return;}LinearLayout box=column();box.setPadding(Ui.dp(this,18),Ui.dp(this,12),Ui.dp(this,18),0);EditText at=new EditText(this);Ui.input(at);at.setContentDescription("Ponto da anotação");at.setHint(item.type.equals("pdf")?"Página":"m:ss ou h:mm:ss");at.setText(item.type.equals("pdf")?String.valueOf((previous==null?item.position:previous.at)+1):VideoLoop.time(previous==null?item.position:previous.at));at.setEnabled(previous==null);box.addView(at,new LinearLayout.LayoutParams(-1,-2));EditText body=new EditText(this);Ui.input(body);body.setSingleLine(false);body.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);body.setMinLines(4);body.setMaxLines(8);body.setGravity(Gravity.TOP);body.setFilters(new InputFilter[]{new InputFilter.LengthFilter(1000)});body.setContentDescription("Texto da anotação");body.setHint("Sua anotação neste ponto");if(previous!=null)body.setText(previous.text);box.addView(body,new LinearLayout.LayoutParams(-1,-2));ScrollView scroll=new ScrollView(this);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(previous==null?"Nova anotação":"Editar anotação").setView(scroll).setPositiveButton("Salvar",null).setNegativeButton("Cancelar",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{long position=-1;try{position=item.type.equals("pdf")?Long.parseLong(at.getText().toString())-1:VideoLoop.parse(at.getText().toString());}catch(NumberFormatException ignored){}if(position<0||(item.duration>0&&position>=(item.type.equals("pdf")?item.duration:item.duration+1))){at.setError("Escolha um ponto dentro do arquivo");return;}if(body.getText().toString().trim().isEmpty()){body.setError("Escreva uma anotação");return;}long anchor=position;boolean ok=ShelfStore.edit(this,s->s.note(item.id,previous==null?"":previous.id,anchor,body.getText().toString()));dialog.dismiss();changed(ok);}));dialog.show();}
 private void open(MediaShelf.Item item,long position){Uri uri=Uri.parse(item.uri);Class<?> target=item.type.equals("pdf")?PdfActivity.class:item.type.equals("video")?VideoActivity.class:MainActivity.class;Intent intent=new Intent(this,target).setAction(Intent.ACTION_VIEW).setDataAndType(uri,item.type.equals("pdf")?"application/pdf":item.type+"/*").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(item.type.equals("pdf"))intent.putExtra("onda_page",(int)position);else intent.putExtra("onda_start_ms",position);try{startActivity(intent);}catch(RuntimeException e){Toast.makeText(this,"Selecione novamente o arquivo pelo botão Adicionar.",Toast.LENGTH_LONG).show();}}
 private void pick(){pickerGroup=group;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"audio/*","video/*","application/pdf"}).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(intent,PICK);}catch(ActivityNotFoundException e){Toast.makeText(this,"Seletor de arquivos indisponível",Toast.LENGTH_LONG).show();}}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request!=PICK||result!=RESULT_OK||intent==null||intent.getData()==null)return;Uri uri=intent.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(RuntimeException ignored){}String owner=pickerGroup;busy=true;render();worker.execute(()->{String name=uri.getLastPathSegment();try{String mime=getContentResolver().getType(uri);try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}String type=mime!=null&&mime.startsWith("audio/")?"audio":mime!=null&&mime.startsWith("video/")?"video":"application/pdf".equals(mime)?"pdf":null;if(type==null&&name!=null){String lower=name.toLowerCase(Locale.ROOT);if(lower.endsWith(".pdf"))type="pdf";else{String guessed=android.webkit.MimeTypeMap.getSingleton().getMimeTypeFromExtension(lower.substring(lower.lastIndexOf('.')+1));if(guessed!=null&&guessed.startsWith("audio/"))type="audio";else if(guessed!=null&&guessed.startsWith("video/"))type="video";}}if(type==null)throw new IllegalArgumentException();String label=name,kind=type;boolean ok=ShelfStore.edit(this,s->{MediaShelf.Item existing=null;for(MediaShelf.Item i:s.items.values())if(i.type.equals(kind)&&i.uri.equals(uri.toString()))existing=i;MediaShelf.Item item=existing!=null?existing:s.touch(kind,uri.toString(),label,0,0,System.currentTimeMillis());return item!=null&&(owner.isEmpty()||s.add(owner,item.id));});runOnUiThread(()->{if(!isDestroyed()){busy=false;changed(ok);}});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()){busy=false;render();Toast.makeText(this,"Escolha um arquivo de áudio, vídeo ou PDF.",Toast.LENGTH_LONG).show();}});}});}
 @Override public void onBackPressed(){if(!group.isEmpty()){group="";render();}else super.onBackPressed();}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
